// seed-evidence: items e1-e7 with states (e5 `failed`/`malformed` — CR-001
// scope change replaces the prototype's "password protected"/`encrypted`
// with `malformed`, since Phase 1 has no PDF/encrypted-file path at all;
// the other six `published`); artifacts generated by `derivatives.ts`
// (`// TODO(T-304): re-seed through the pipeline`); custody events
// `received…published` per item; `original_sha256` of the generated
// source; no original artifact rows are public; `retention_expires_at =
// published_at + 90 d`.
import { fileURLToPath } from 'node:url';
import path from 'node:path';

import { newId, newPublicId } from '@rogikotha/contracts';
import {
  evidenceArtifacts,
  evidenceCustodyEvents,
  evidenceItems,
  personaLinks,
  reviews,
  type Db,
} from '@rogikotha/database';
import { eq } from 'drizzle-orm';

import { EVIDENCE_ITEMS } from '../corpus/index.js';
import { generateDerivatives, generateOriginal } from './derivatives.js';
import type { SeedContext } from './seed.js';

// `STORAGE_ROOT` in `.env` is `./.data/storage`, a relative path with no
// documented anchor. Resolved here against the repo root (not
// `process.cwd()`, which is `packages/test-support` when this runs via
// `pnpm --filter @rogikotha/test-support seed` — a relative path would
// otherwise land at `packages/test-support/.data/storage` instead of the
// repo-root `.data/storage` every other tool expects). Absolute values in
// `STORAGE_ROOT` are used as-is.
const repoRootForStorage = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '..',
  '..',
  '..',
  '..',
);
const STORAGE_ROOT = path.isAbsolute(process.env.STORAGE_ROOT ?? '')
  ? process.env.STORAGE_ROOT!
  : path.resolve(repoRootForStorage, process.env.STORAGE_ROOT ?? './.data/storage');
const NINETY_DAYS_MS = 90 * 24 * 60 * 60 * 1000;

export async function seedEvidence(db: Db, ctx: SeedContext): Promise<number> {
  let inserted = 0;

  for (const item of EVIDENCE_ITEMS) {
    const [existing] = await db
      .select()
      .from(evidenceItems)
      .where(eq(evidenceItems.seedRef, item.seedRef))
      .limit(1);
    if (existing) {
      ctx.evidenceItemIdBySeedRef.set(item.seedRef, existing.id);
      ctx.evidenceItemPublicIdBySeedRef.set(item.seedRef, existing.publicId);
      continue;
    }
    const reviewId = ctx.reviewIdBySeedRef.get(item.reviewSeedRef);
    if (!reviewId)
      throw new Error(
        `seed-evidence: item ${item.seedRef} references unseeded review ${item.reviewSeedRef}`,
      );
    const [review] = await db.select().from(reviews).where(eq(reviews.id, reviewId)).limit(1);
    if (!review) throw new Error(`seed-evidence: review ${item.reviewSeedRef} not found`);
    // The uploader is whichever account the review's persona is linked to
    // (an anonymous persona is still linked to a real account, privately).
    const [link] = await db
      .select()
      .from(personaLinks)
      .where(eq(personaLinks.personaId, review.authorPersonaId))
      .limit(1);
    const uploadedByAccountId = link?.accountId;
    if (!uploadedByAccountId)
      throw new Error(
        `seed-evidence: no account linked to persona of review ${item.reviewSeedRef}`,
      );

    // Scope change (CR-001/FD-036): images only, one page, no PDFs; e5 fails
    // `malformed` (the prototype's "password protected" has no Phase 1
    // equivalent — `encrypted` is a Phase 2 fail reason, reserved unused).
    const failed = item.prototypeState === 'failed';
    const publicId = newPublicId();
    const original = generateOriginal(publicId, item.label.en);
    const now = new Date();

    const [row] = await db
      .insert(evidenceItems)
      .values({
        id: newId(),
        publicId,
        seedRef: item.seedRef,
        reviewId,
        group: item.group,
        labelEn: item.label.en,
        labelBn: item.label.bn,
        state: failed ? 'failed' : 'published',
        failReason: failed ? 'malformed' : undefined,
        declaredMime: 'image/jpeg',
        detectedMime: failed ? undefined : 'image/jpeg',
        originalBytes: original.bytes.length,
        originalSha256: original.sha256,
        originalFilenameEnc: original.bytes.subarray(0, 32), // TODO(T-304): real Crypto-port encryption once that adapter exists.
        pageCount: 1,
        uploadedByAccountId,
        retentionExpiresAt: failed ? null : new Date(now.getTime() + NINETY_DAYS_MS),
      })
      .returning();
    ctx.evidenceItemIdBySeedRef.set(item.seedRef, row!.id);
    ctx.evidenceItemPublicIdBySeedRef.set(item.seedRef, publicId);
    inserted += 1;

    await db
      .insert(evidenceCustodyEvents)
      .values({ id: newId(), itemId: row!.id, event: 'received', actor: 'worker' });
    inserted += 1;

    if (failed) {
      await db.insert(evidenceCustodyEvents).values({
        id: newId(),
        itemId: row!.id,
        event: 'validation_failed',
        actor: 'worker',
        details: { reason: 'malformed' },
      });
      inserted += 1;
      continue;
    }

    for (const event of [
      'validated',
      'scan_clean',
      'sanitised',
      'preview_ready',
      'privacy_confirmed',
      'published',
    ] as const) {
      await db
        .insert(evidenceCustodyEvents)
        .values({ id: newId(), itemId: row!.id, event, actor: 'worker' });
      inserted += 1;
    }

    const artifacts = await generateDerivatives(STORAGE_ROOT, publicId, item.label.en, 1, true);
    let publishedArtifactId: string | null = null;
    for (const artifact of artifacts) {
      const [artifactRow] = await db
        .insert(evidenceArtifacts)
        .values({
          id: newId(),
          itemId: row!.id,
          kind: artifact.kind,
          pageNo: artifact.pageNo,
          storageKey: artifact.storageKey,
          sha256: artifact.sha256,
          bytes: artifact.bytes.length,
          mime: 'image/png',
          width: artifact.width,
          height: artifact.height,
          sanitiserVersion: 'seed-1',
          immutable: true,
          public: true,
        })
        .returning();
      if (artifact.kind === 'page_png') publishedArtifactId = artifactRow!.id;
      inserted += 1;
    }
    if (publishedArtifactId) {
      await db
        .update(evidenceItems)
        .set({ publishedArtifactId })
        .where(eq(evidenceItems.id, row!.id));
    }
  }

  return inserted;
}
